// ── GST / Cost structure (from exporters/excel.py) ──
// Materials (A) + Labour (B)
// Supervision = (A+B) * supervision_rate
// GST = B * 0.18  (on labour only, materials already inclusive of GST per database.py)
// Sub-Total = A + B + Supervision + GST
// Cess = (A + B + Supervision) * 0.01
// Grand Total = Sub-Total + Cess

function buildContext(obj, objType) {
  const meta = project.project_meta;
  const ctx = { ...obj, project_type: meta.project_type, use_uh: meta.use_uh, supervision_rate: meta.supervision_rate };
  const connected = project.spans.filter(s => s.from_id === obj.id || s.to_id === obj.id);
  if (objType === 'SmartPole' || objType === 'SmartStructure') {
    ctx.is_new    = !obj.is_existing;
    ctx.is_existing = !!obj.is_existing;
    ctx.ht_spans_count  = connected.filter(s => s.is_ht_span).length;
    ctx.lt_acsr_count   = connected.filter(s => !s.is_service_drop && s.conductor === 'ACSR' && s.is_lt_span).length;
    ctx.lt_pvc_count    = connected.filter(s => !s.is_service_drop && s.conductor === 'PVC Cable' && s.is_lt_span).length;
    ctx.ab_cable_count  = connected.filter(s => s.conductor === 'AB Cable' && !s.is_service_drop).length;
    ctx.ab_new_cable_count = connected.filter(s => s.conductor === 'AB Cable' && !s.is_service_drop && !s.is_existing_span).length;
    const ltSpans = connected.filter(s => s.is_lt_span && !s.is_service_drop);
    ctx.lt_wire_count = ltSpans.length > 0 ? Math.max(...ltSpans.map(s => Number(s.wire_count) || 0)) : 0;
    ctx.ab_needs_dead_end  = ctx.ab_cable_count === 1;
    ctx.ab_needs_suspension = ctx.ab_cable_count >= 2;
    ctx.kiosk_required = !!obj.dtr_kiosk_required;
    ctx.dtr_aug_required = false;
    ctx.dtr_structure_change_required = false;
    ctx.has_cg = !!obj.has_cg;
    ctx.height  = Number(obj.height) || 0;
  } else if (objType === 'SmartSpan') {
    ctx.is_new_span = !obj.is_existing_span;
    ctx.is_distribution_span = !obj.is_service_drop;
    ctx.length = Number(obj.length) || 40;
    ctx.wire_count = Number(obj.wire_count) || 4;
    ctx.cable_size = obj.conductor_size;
    ctx.conductor_aug_required = false;
    ctx.aug_to_config = 'None';
  } else if (objType === 'SmartConsumer') {
    ctx.is_new = true; ctx.is_existing = false;
    ctx.agency_supply = !!obj.agency_supply;
    ctx.consider_cable = obj.consider_cable !== false;
    const svcSpan = project.spans.find(s => s.to_id === obj.id || s.from_id === obj.id);
    ctx.service_length = svcSpan ? (Number(svcSpan.length) || 20) : 20;
  }
  return ctx;
}

function evalCond(cond, ctx) {
  try {
    const js = cond
      .replace(/\bTrue\b/g,'true').replace(/\bFalse\b/g,'false').replace(/\bNone\b/g,'null')
      .replace(/\bnot\s+/g,'!').replace(/\band\b/g,'&&').replace(/\bor\b/g,'||')
      .replace(/(\w+)\s+in\s+\(([^)]+)\)/g, (m,v,lst) => {
        const items = lst.split(',').map(i=>i.trim()); return `[${items.join(',')}].includes(${v})`;
      })
      .replace(/(\w+)\s+not\s+in\s+\(([^)]+)\)/g, (m,v,lst) => {
        const items = lst.split(',').map(i=>i.trim()); return `![${items.join(',')}].includes(${v})`;
      });
    const fn = new Function(...Object.keys(ctx), `return (${js});`);
    return fn(...Object.values(ctx));
  } catch(e) { return false; }
}

